/**
 * Real catalogue data, imported from the live JORCUSTOM catalogue.
 *
 * `products.json` and `designs.json` are generated by
 * `scripts/fetch_real_catalog.py` + `scripts/build_catalog.py` from the real
 * API, so the storefront runs on the real products, sizes, colourways and
 * print designs (including every artwork layer used by the Customize Tool).
 *
 * The designs bundle is loaded on demand — only the Customize Tool needs it.
 */
import type { Category, Collection, ColorTheme, Design, Product, ProductColor } from "../types";

import rawCatalog from "./products.json";

interface RawSize {
  label: string;
  quantity: number;
}

interface RawProduct {
  slug: string;
  name: string;
  new: boolean;
  priceCents: number;
  discountPriceCents: number | null;
  color: { name: string; hex: string };
  category: { name: string; slug: string };
  collections: { name: string; slug: string }[];
  images: string[];
  sizes: RawSize[];
  description: number;
  descriptionEn: number;
  sizeReference: number;
  sizeReferenceEn: number;
  designIds: string[];
}

export interface RawDesignLayer {
  id: string;
  name: string;
  layerType: string;
  image: string | null;
  editableColor: boolean;
  editableText: boolean;
  printable: boolean;
  defaultColor: string | null;
  position: number;
  width: number;
  height: number;
  x: number;
  y: number;
  minChars: number | null;
  maxChars: number | null;
}

export interface RawDesign {
  id: string;
  name: string;
  thumbnail: string | null;
  projection: string | null;
  canvasWidth: number;
  canvasHeight: number;
  layers: RawDesignLayer[];
}

const catalog = rawCatalog as unknown as {
  products: RawProduct[];
  texts: string[];
  colorThemes: { id: string; name: string; colors: string[] }[];
};

const texts = catalog.texts;
const raw = catalog.products;

const SIZE_ORDER = [
  "2XS",
  "XS",
  "S",
  "M",
  "L",
  "XL",
  "XXL",
  "2XL",
  "3XL",
  "4XL",
  "5XL",
  "6XL",
  "ONE SIZE",
];

function sizeRank(label: string) {
  const index = SIZE_ORDER.indexOf(label);
  if (index >= 0) return index;
  const numeric = Number(label);
  return Number.isFinite(numeric) ? 100 + numeric : 999;
}

/** Slug-safe id for a colourway, e.g. "Acid-Pink" -> "acid-pink". */
function colorId(product: RawProduct) {
  const category = product.category.slug;
  if (category && product.slug.includes(category)) {
    const tail = product.slug.split(category)[1]?.replace(/^-+/, "");
    if (tail) return tail;
  }
  return product.color.name.toLowerCase().replace(/[^a-z0-9]+/g, "-") || product.slug;
}

/** Products that are the same garment in another colourway share this key. */
function familyKey(product: RawProduct) {
  const category = product.category.slug;
  if (category && product.slug.includes(category)) {
    const head = product.slug.split(category)[0]?.replace(/-+$/, "");
    if (head) return `${category}|${head}`;
  }
  return `${category}|${product.slug}`;
}

function prettyColorName(value: string) {
  return value
    .replace(/[-_]+/g, " ")
    .replace(/([a-z])([A-Z])/g, "$1 $2")
    .replace(/\s+/g, " ")
    .trim()
    .replace(/\b\w/g, (c) => c.toUpperCase());
}

function bulletDetails(text: string) {
  return text
    .split("\n")
    .map((line) => line.trim())
    .filter((line) => line.startsWith("•"))
    .map((line) => line.replace(/^•\s*/, ""));
}

const families = new Map<string, RawProduct[]>();
for (const product of raw) {
  const key = familyKey(product);
  const list = families.get(key);
  if (list) list.push(product);
  else families.set(key, [product]);
}

function colorOptions(product: RawProduct): ProductColor[] {
  const family = families.get(familyKey(product)) ?? [product];
  const ordered = [product, ...family.filter((p) => p.slug !== product.slug)];
  const seen = new Set<string>();
  const options: ProductColor[] = [];
  for (const item of ordered) {
    const id = colorId(item);
    if (seen.has(id)) continue;
    seen.add(id);
    const label = prettyColorName(id);
    options.push({
      id,
      name: { nl: label, en: label },
      hex: item.color.hex || "#141414",
      image: item.images[0] ?? "",
      productSlug: item.slug,
    });
  }
  return options;
}

export const realProducts: Product[] = raw.map((product, index) => {
  const detailsNl = bulletDetails(texts[product.description] ?? "");
  const detailsEn = bulletDetails(texts[product.descriptionEn] ?? "");
  const collections = product.collections.map((c) => c.slug);

  return {
    id: product.slug,
    slug: product.slug,
    name: product.name,
    category: product.category.slug,
    collections,
    priceCents: product.discountPriceCents ?? product.priceCents,
    compareAtCents: product.discountPriceCents ? product.priceCents : undefined,
    colors: colorOptions(product),
    sizes: [...product.sizes]
      .sort((a, b) => sizeRank(a.label) - sizeRank(b.label))
      .map((size) => ({ label: size.label, inStock: size.quantity !== 0 })),
    images: product.images,
    customizable: product.designIds.length > 0,
    designId: product.designIds[0],
    designIds: product.designIds,
    isNew: product.new || collections.includes("new") || collections.includes("new-arrivals"),
    description: {
      nl: texts[product.description] ?? "",
      en: texts[product.descriptionEn] ?? texts[product.description] ?? "",
    },
    details: detailsNl.map((nl, i) => ({ nl, en: detailsEn[i] ?? nl })),
    sizing: {
      nl: texts[product.sizeReference] ?? "",
      en: texts[product.sizeReferenceEn] ?? texts[product.sizeReference] ?? "",
    },
    createdAt: new Date(Date.UTC(2026, 0, 1) - index * 86_400_000).toISOString(),
  };
});

const HIDDEN_COLLECTIONS = new Set(["shop"]);

const collectionMeta = new Map<string, { name: string; image: string; count: number }>();
for (const product of raw) {
  for (const collection of product.collections) {
    const existing = collectionMeta.get(collection.slug);
    if (existing) existing.count += 1;
    else
      collectionMeta.set(collection.slug, {
        name: collection.name,
        image: product.images[0] ?? "",
        count: 1,
      });
  }
}

export const realCollections: Collection[] = [...collectionMeta]
  .filter(([slug]) => !HIDDEN_COLLECTIONS.has(slug))
  .sort((a, b) => b[1].count - a[1].count)
  .map(([slug, meta], index) => ({
    slug,
    title: meta.name,
    subtitle: {
      nl: `${meta.count} items in deze collectie.`,
      en: `${meta.count} items in this collection.`,
    },
    image: meta.image,
    featured: index < 4,
  }));

const categoryMeta = new Map<string, { name: string; count: number }>();
for (const product of raw) {
  if (!product.category.slug) continue;
  const existing = categoryMeta.get(product.category.slug);
  if (existing) existing.count += 1;
  else categoryMeta.set(product.category.slug, { name: product.category.name, count: 1 });
}

export const realCategories: Category[] = [...categoryMeta]
  .sort((a, b) => b[1].count - a[1].count)
  .map(([slug, meta]) => ({
    slug,
    name: { nl: meta.name, en: meta.name },
    group: slug.startsWith("sale") ? "sale" : "shop",
  }));

export const realColorThemes: ColorTheme[] = catalog.colorThemes.map((theme) => ({
  id: theme.id,
  name: { nl: theme.name, en: theme.name },
  colors: theme.colors,
}));

let designCache: Record<string, Design> | null = null;

/**
 * Design files are named like
 * `Men_FW25_AboveAllLimits_DoubleLayeredLongsleeveT-Shirt_Acid-Pink_Front`.
 * Show the artwork name instead of the production filename.
 */
function designDisplayName(raw: RawDesign) {
  const parts = raw.name.split("_").filter(Boolean);
  const artwork = parts[2] ?? parts[parts.length - 1] ?? raw.name;
  return artwork.replace(/([a-z0-9])([A-Z])/g, "$1 $2").replace(/-/g, " ").trim();
}

function toDesign(raw: RawDesign): Design {
  return {
    id: raw.id,
    name: designDisplayName(raw),
    thumbnail: raw.thumbnail,
    projection: raw.projection ?? "front",
    canvasWidth: raw.canvasWidth,
    canvasHeight: raw.canvasHeight,
    layers: raw.layers.map((layer) => ({
      id: layer.id,
      name: layer.name,
      image: layer.image,
      editableColor: layer.editableColor,
      editableText: layer.editableText,
      printable: layer.printable,
      defaultColor: layer.defaultColor ?? "#ffffff",
      position: layer.position,
      x: layer.x,
      y: layer.y,
      width: layer.width,
      height: layer.height,
    })),
  };
}

/** Lazily load the design/layer bundle (only the Customize Tool needs it). */
export async function loadDesigns(): Promise<Record<string, Design>> {
  if (designCache) return designCache;
  const module = await import("./designs.json");
  const source = (module.default ?? module) as unknown as Record<string, RawDesign>;
  designCache = Object.fromEntries(
    Object.entries(source).map(([id, design]) => [id, toDesign(design)]),
  );
  return designCache;
}
